userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div><b>Stage</b></div>
<button id="stgAtomic">Atomic orbitals</button>
<button id="stgHybrids">sp3 hybrids</button>
<button id="stgTetra">Tetrahedral</button>
<hr style="width:100%;border:0;border-top:1px solid #ddd">
<div><b>Orbital contributions</b></div>
<label style="flex-direction:row;align-items:center;gap:4px"><input type="checkbox" id="chkS" checked> s orbital</label>
<label style="flex-direction:row;align-items:center;gap:4px"><input type="checkbox" id="chkPx" checked> pₓ orbital</label>
<label style="flex-direction:row;align-items:center;gap:4px"><input type="checkbox" id="chkPy" checked> p_y orbital</label>
<label style="flex-direction:row;align-items:center;gap:4px"><input type="checkbox" id="chkPz" checked> p_z orbital</label>
<hr style="width:100%;border:0;border-top:1px solid #ddd">
<div><b>Demo</b></div>
<button id="btnPrev">◀ Prev step</button>
<button id="btnNext">Next step ▶</button>
<div id="stepTitle" style="font-weight:bold"></div>
<div id="stepText" style="font-size:11px;color:#444;white-space:normal"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// axes       → Line segments + ConeGeometry arrowheads, black
// s orbital  → SphereGeometry(0.7) translucent blue
// p lobes    → SphereGeometry scaled (0.5,1.1,0.5), blue + / red −, along axis
// sp3 lobes  → SphereGeometry scaled big (0.55,1.5,0.55) + small (0.25,0.4,0.25), orange
// tetra rays → dashed grey lines to 4 tetrahedron vertices
const BLUE = 0x5b84c4, RED = 0xd9534f, ORANGE = 0xf0a03c;
const AXLEN = 2.5;

// ---- axis triad with arrowheads ----
const axesGroup = new THREE.Group();
scene.add(axesGroup);
function addAxis(dir) {
  const d3 = dir.clone().normalize();
  const mat = new THREE.LineBasicMaterial({ color: 0x111111 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(AXLEN)]), mat);
  axesGroup.add(line);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.2, 12),
    new THREE.MeshBasicMaterial({ color: 0x111111 }));
  cone.position.copy(d3.clone().multiplyScalar(AXLEN + 0.1));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3);
  axesGroup.add(cone);
  // short negative stub
  const stub = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(-0.7)]), mat);
  axesGroup.add(stub);
}
addAxis(new THREE.Vector3(1, 0, 0));
addAxis(new THREE.Vector3(0, 0, 1));
addAxis(new THREE.Vector3(0, 1, 0));

// ---- orbital materials ----
function orbMat(color, opacity) {
  return new THREE.MeshPhongMaterial({
    color, transparent: true, opacity, shininess: 60,
    specular: 0x888888, side: THREE.DoubleSide, depthWrite: false
  });
}
scene.add(new THREE.AmbientLight(0xffffff, 0.9));
const dl = new THREE.DirectionalLight(0xffffff, 0.8);
dl.position.set(3, 5, 4);
scene.add(dl);

// ---- atomic orbitals group ----
const atomicGroup = new THREE.Group();
scene.add(atomicGroup);

// s: sphere radius 0.7
const sOrb = new THREE.Mesh(new THREE.SphereGeometry(0.7, 48, 32), orbMat(BLUE, 0.55));
atomicGroup.add(sOrb);

// p orbital: two scaled-sphere lobes along given axis
function makePOrbital(axis) {
  const g = new THREE.Group();
  const d3 = axis.clone().normalize();
  const geo = new THREE.SphereGeometry(0.5, 32, 24);
  geo.scale(1, 2.2, 1); // 0.5 wide x 1.1 long (half-length 1.1)
  const pos = new THREE.Mesh(geo, orbMat(BLUE, 0.6));
  pos.position.copy(d3.clone().multiplyScalar(0.95));
  pos.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3);
  const neg = new THREE.Mesh(geo.clone(), orbMat(RED, 0.6));
  neg.position.copy(d3.clone().multiplyScalar(-0.95));
  neg.quaternion.copy(pos.quaternion);
  g.add(pos, neg);
  return g;
}
const pxOrb = makePOrbital(new THREE.Vector3(1, 0, 0));
const pyOrb = makePOrbital(new THREE.Vector3(0, 0, 1));
const pzOrb = makePOrbital(new THREE.Vector3(0, 1, 0));
atomicGroup.add(pxOrb, pyOrb, pzOrb);

// ---- sp3 hybrids ----
const TETRA = [
  new THREE.Vector3(1, 1, 1), new THREE.Vector3(1, -1, -1),
  new THREE.Vector3(-1, 1, -1), new THREE.Vector3(-1, -1, 1)
].map(v => v.normalize());

const hybridGroup = new THREE.Group();
scene.add(hybridGroup);
function makeHybrid(dir) {
  const g = new THREE.Group();
  const big = new THREE.SphereGeometry(0.55, 32, 24);
  big.scale(1, 1.5 / 0.55 * 0.5 + 0.85, 1); // ~0.55 wide, 1.5 long overall
  const bigMesh = new THREE.Mesh(big, orbMat(ORANGE, 0.75));
  bigMesh.position.set(0, 0.62, 0);
  const small = new THREE.SphereGeometry(0.25, 24, 16);
  small.scale(1, 1.6, 1);
  const smallMesh = new THREE.Mesh(small, orbMat(ORANGE, 0.6));
  smallMesh.position.set(0, -0.32, 0);
  g.add(bigMesh, smallMesh);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  return g;
}
const hybrids = TETRA.map(makeHybrid);
hybrids.forEach(h => hybridGroup.add(h));

// ---- tetrahedral dashed guide lines ----
const tetraGroup = new THREE.Group();
scene.add(tetraGroup);
TETRA.forEach(dir => {
  const geo = new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), dir.clone().multiplyScalar(2.2)]);
  const line = new THREE.Line(geo, new THREE.LineDashedMaterial({
    color: 0x999999, dashSize: 0.12, gapSize: 0.09
  }));
  line.computeLineDistances();
  tetraGroup.add(line);
});
// tetrahedron edges (wireframe) for clarity
{
  const v = TETRA.map(d3 => d3.clone().multiplyScalar(2.2));
  const pts = [];
  for (let i = 0; i < 4; i++) for (let j = i + 1; j < 4; j++) pts.push(v[i], v[j]);
  const edges = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0xbbbbbb, transparent: true, opacity: 0.6 }));
  tetraGroup.add(edges);
}

// ---- stage state ----
let stage = 'Tetrahedral';
function applyStage() {
  atomicGroup.visible = stage === 'Atomic orbitals';
  hybridGroup.visible = stage !== 'Atomic orbitals';
  tetraGroup.visible = stage === 'Tetrahedral';
  for (const [id, on] of [['stgAtomic', 'Atomic orbitals'], ['stgHybrids', 'sp3 hybrids'], ['stgTetra', 'Tetrahedral']])
    document.getElementById(id).classList.toggle('active', stage === on);
  stageLabel.div.innerHTML = '<b>' + (stage === 'Tetrahedral' ? 'Tetrahedral arrangement' : stage) + '</b>';
  // contribution toggles only meaningful in Atomic orbitals stage
  applyToggles();
}
function applyToggles() {
  sOrb.visible = document.getElementById('chkS').checked;
  pxOrb.visible = document.getElementById('chkPx').checked;
  pyOrb.visible = document.getElementById('chkPy').checked;
  pzOrb.visible = document.getElementById('chkPz').checked;
}
document.getElementById('stgAtomic').onclick = () => { stage = 'Atomic orbitals'; applyStage(); };
document.getElementById('stgHybrids').onclick = () => { stage = 'sp3 hybrids'; applyStage(); };
document.getElementById('stgTetra').onclick = () => { stage = 'Tetrahedral'; applyStage(); };
['chkS', 'chkPx', 'chkPy', 'chkPz'].forEach(id =>
  document.getElementById(id).addEventListener('change', applyToggles));

// ---- camera (after geometry) ----
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.65 });

// ---- labels ----
addLabel('<i>x</i>', new THREE.Vector3(AXLEN + 0.35, 0, 0), { fontSize: '15px', bold: true });
addLabel('<i>z</i>', new THREE.Vector3(0, AXLEN + 0.35, 0), { fontSize: '15px', bold: true });
addLabel('<i>y</i>', new THREE.Vector3(0, 0, AXLEN + 0.35), { fontSize: '15px', bold: true });
const stageLabel = addLabel('<b>Tetrahedral arrangement</b>', new THREE.Vector3(0, -2.9, 0), { fontSize: '15px' });

// ---- demo steps ----
const steps = [
  {
    title: 'Atomic orbitals',
    narration: 'Before hybridization: a spherical s orbital and three mutually perpendicular p orbitals, each with red (negative) and blue (positive) lobes. Toggle each contribution off and on to see it alone.',
    state: { stage: 'Atomic orbitals', chkS: true, chkPx: true, chkPy: true, chkPz: true }
  },
  {
    title: 'Four sp3 hybrids',
    narration: 'After hybridization the orbital distinctions are gone: four equivalent orange hybrids, each with a large lobe and a small back-lobe, point in four different directions.',
    state: { stage: 'sp3 hybrids' }
  },
  {
    title: 'Tetrahedral arrangement',
    narration: 'Viewed together, the four large lobes point to the corners of a tetrahedron at 109.5° to each other — the geometry behind CH4 and other tetrahedral molecules. Orbit to appreciate the symmetry.',
    state: { stage: 'Tetrahedral' }
  }
];
let stepIdx = 2;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  stage = st.state.stage;
  for (const id of ['chkS', 'chkPx', 'chkPy', 'chkPz'])
    if (id in st.state) document.getElementById(id).checked = st.state[id];
  applyStage();
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.narration;
}
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
goToStep(2);

// interactivity on hybrids
hybrids.forEach((h, i) => registerInteractive(h, {
  title: 'sp³ hybrid orbital ' + (i + 1),
  tooltip: 'sp³ hybrid — large lobe to a tetrahedron corner',
  body: 'Each sp³ hybrid is the combination ½(s ± pₓ ± p_y ± p_z). Its large lobe points to a tetrahedron corner; any two lobes meet at 109.47°. The small back-lobe is the opposite-sign remnant.'
}));
registerInteractive(sOrb, {
  title: 's orbital', tooltip: 'Spherical s orbital',
  body: 'The s orbital has equal amplitude in all directions. Mixed into each hybrid, it rounds out the large lobe.'
});
// @FIGURE_CODE_END

