<div id="stepText" style="font-size:11px;color:#444;white-space:normal"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// mini axis triad → Line segments + ConeGeometry arrowheads, black, length 1.15 (one per panel)
// s orbital   → SphereGeometry(0.5) translucent blue, own mini-panel
// p lobe      → LatheGeometry teardrop (rounded tip, pinched at origin), blue + / red −
// sp3 big lobe→ LatheGeometry teardrop (1.5 long, 0.52 wide), orange
// sp3 back    → small LatheGeometry teardrop (0.42 long, 0.2 wide), orange
// NOTE: tetrahedron wireframe, dashed guide rays and 109.5° label removed (not in source)
const BLUE = 0x5b84c4, RED = 0xd9534f, ORANGE = 0xef9f38;

// ---- lighting ----
scene.add(new THREE.AmbientLight(0xffffff, 0.95));
const dl = new THREE.DirectionalLight(0xffffff, 0.7);
dl.position.set(3, 5, 4);
scene.add(dl);

function orbMat(color, opacity) {
  return new THREE.MeshPhongMaterial({
    color, transparent: true, opacity, shininess: 50,
    specular: 0x666666, side: THREE.DoubleSide, depthWrite: false
  });
}

// ---- teardrop lobe via lathe: r(t) = sin(pi*t^p)*w, y = t*L, pinched at t=0 ----
function teardropGeo(len, wid, pinch) {
  const pts = [];
  const N = 40;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const r = Math.sin(Math.PI * Math.pow(t, pinch)) * wid;
    pts.push(new THREE.Vector2(Math.max(r, 0.001), t * len));
  }
  return new THREE.LatheGeometry(pts, 40);
}
const pLobeGeo = teardropGeo(0.75, 0.33, 0.62);      // p lobe for mini-panels
const sp3BigGeo = teardropGeo(1.5, 0.52, 0.55);
const sp3SmallGeo = teardropGeo(0.42, 0.2, 0.6);

// ---- one mini-panel: small axis triad + one orbital, matches source's per-panel layout ----
const MINI_AX = 1.15;
function makeMiniPanel(origin) {
  const g = new THREE.Group();
  g.position.copy(origin);
  function ax(dir) {
    const d3 = dir.clone().normalize();
    const mat = new THREE.LineBasicMaterial({ color: 0x111111 });
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(MINI_AX)]), mat));
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.15, 10),
      new THREE.MeshBasicMaterial({ color: 0x111111 }));
    cone.position.copy(d3.clone().multiplyScalar(MINI_AX + 0.08));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3);
    g.add(cone);
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(-0.55)]), mat));
  }
  ax(new THREE.Vector3(1, 0, 0));
  ax(new THREE.Vector3(0, 0, 1));
  ax(new THREE.Vector3(0, 1, 0));
  scene.add(g);
  return g;
}
function makePOrbital(axis, geo, scale) {
  const g = new THREE.Group();
  const d3 = axis.clone().normalize();
  const pos = new THREE.Mesh(geo, orbMat(BLUE, 0.65));
  pos.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3);
  const neg = new THREE.Mesh(geo, orbMat(RED, 0.65));
  neg.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3.clone().negate());
  if (scale) g.scale.setScalar(scale);
  g.add(pos, neg);
  return g;
}

// ---- Atomic orbitals stage: four offset mini-panels in a 2x2 spread (source layout) ----
const atomicGroup = new THREE.Group();
scene.add(atomicGroup);
const OFF = 2.35;
const panelDefs = [
  { name: 's',    pos: new THREE.Vector3(-OFF,  OFF, 0) },
  { name: 'pₓ',   pos: new THREE.Vector3( OFF,  OFF, 0) },
  { name: 'p_y',  pos: new THREE.Vector3(-OFF, -OFF, 0) },
  { name: 'p_z',  pos: new THREE.Vector3( OFF, -OFF, 0) },
];
const miniPanels = panelDefs.map(d => { const p = makeMiniPanel(d.pos); atomicGroup.add(p); return p; });

const sOrb = new THREE.Mesh(new THREE.SphereGeometry(0.5, 40, 28), orbMat(BLUE, 0.55));
miniPanels[0].add(sOrb);
const pxOrb = makePOrbital(new THREE.Vector3(1, 0, 0), pLobeGeo);
const pyOrb = makePOrbital(new THREE.Vector3(0, 0, 1), pLobeGeo);
const pzOrb = makePOrbital(new THREE.Vector3(0, 1, 0), pLobeGeo);
miniPanels[1].add(pxOrb);
miniPanels[2].add(pyOrb);
miniPanels[3].add(pzOrb);

// ---- sp3 hybrids stage: single central scene, four equivalent hybrids ----
const TETRA = [
  new THREE.Vector3(1, 1, 1), new THREE.Vector3(1, -1, -1),
  new THREE.Vector3(-1, 1, -1), new THREE.Vector3(-1, -1, 1)
].map(v => v.normalize());

const hybridGroup = new THREE.Group();
scene.add(hybridGroup);
// central full-size axis triad for the hybrid stages
const AXLEN = 2.5;
(function addCentralAxes() {
  function ax(dir) {
    const d3 = dir.clone().normalize();
    const mat = new THREE.LineBasicMaterial({ color: 0x111111 });
    hybridGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(AXLEN)]), mat));
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.2, 12),
      new THREE.MeshBasicMaterial({ color: 0x111111 }));
    cone.position.copy(d3.clone().multiplyScalar(AXLEN + 0.1));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d3);
    hybridGroup.add(cone);
    hybridGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, 0, 0), d3.clone().multiplyScalar(-0.7)]), mat));
  }
  ax(new THREE.Vector3(1, 0, 0));
  ax(new THREE.Vector3(0, 0, 1));
  ax(new THREE.Vector3(0, 1, 0));
})();
function makeHybrid(dir) {
  const g = new THREE.Group();
  const big = new THREE.Mesh(sp3BigGeo, orbMat(ORANGE, 0.8));
  big.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  const small = new THREE.Mesh(sp3SmallGeo, orbMat(ORANGE, 0.6));
  small.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().negate());
  g.add(big, small);
  return g;
}
const hybrids = TETRA.map(makeHybrid);
hybrids.forEach(h => hybridGroup.add(h));

// ---- stage state ----
let stage = 'Tetrahedral';
const orbitalLabels = []; // per-panel name labels, Atomic orbitals stage only
const miniAxisLabels = []; // x/y/z labels on mini-panels
const centralAxisLabels = []; // x/y/z labels on the hybrid-stage triad
function applyStage() {
  const isAtomic = stage === 'Atomic orbitals';
  atomicGroup.visible = isAtomic;
  hybridGroup.visible = !isAtomic;
  for (const [id, on] of [['stgAtomic', 'Atomic orbitals'], ['stgHybrids', 'sp3 hybrids'], ['stgTetra', 'Tetrahedral']])
    document.getElementById(id).classList.toggle('active', stage === on);
  stageLabel.div.innerHTML = '<b>' + (stage === 'Tetrahedral' ? 'Tetrahedral arrangement' : stage) + '</b>';
  hybLabel.div.style.display = isAtomic ? '' : 'none';
  tetrLabel.div.style.display = stage === 'Tetrahedral' ? '' : 'none';
  miniAxisLabels.forEach(e => { e.div.style.display = isAtomic ? '' : 'none'; });
  centralAxisLabels.forEach(e => { e.div.style.display = isAtomic ? 'none' : ''; });
  applyToggles();
}
function applyToggles() {
  const isAtomic = stage === 'Atomic orbitals';
  sOrb.visible = document.getElementById('chkS').checked;
  pxOrb.visible = document.getElementById('chkPx').checked;
  pyOrb.visible = document.getElementById('chkPy').checked;
  pzOrb.visible = document.getElementById('chkPz').checked;
  const vis = [sOrb.visible, pxOrb.visible, pyOrb.visible, pzOrb.visible];
  orbitalLabels.forEach((e, i) => { e.div.style.display = isAtomic && vis[i] ? '' : 'none'; });
}
document.getElementById('stgAtomic').onclick = () => { stage = 'Atomic orbitals'; applyStage(); };
document.getElementById('stgHybrids').onclick = () => { stage = 'sp3 hybrids'; applyStage(); };
document.getElementById('stgTetra').onclick = () => { stage = 'Tetrahedral'; applyStage(); };
['chkS', 'chkPx', 'chkPy', 'chkPz'].forEach(id =>
  document.getElementById(id).addEventListener('change', applyToggles));

// ---- camera (after geometry) ----
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.68 });

// ---- labels ----
// mini-panel axis labels (small, one set per panel)
panelDefs.forEach((d, i) => {
  const o = d.pos;
  miniAxisLabels.push(addLabel('<i>x</i>', o.clone().add(new THREE.Vector3(MINI_AX + 0.22, 0, 0)), { fontSize: '11px' }));
  miniAxisLabels.push(addLabel('<i>z</i>', o.clone().add(new THREE.Vector3(0, MINI_AX + 0.22, 0)), { fontSize: '11px' }));
  miniAxisLabels.push(addLabel('<i>y</i>', o.clone().add(new THREE.Vector3(0, 0, MINI_AX + 0.22)), { fontSize: '11px' }));
});
// central axis labels (hybrid stages)
centralAxisLabels.push(addLabel('<i>x</i>', new THREE.Vector3(AXLEN + 0.35, 0, 0), { fontSize: '15px', bold: true }));
centralAxisLabels.push(addLabel('<i>z</i>', new THREE.Vector3(0, AXLEN + 0.35, 0), { fontSize: '15px', bold: true }));
centralAxisLabels.push(addLabel('<i>y</i>', new THREE.Vector3(0, 0, AXLEN + 0.35), { fontSize: '15px', bold: true }));

const stageLabel = addLabel('<b>Tetrahedral arrangement</b>', new THREE.Vector3(0, -3.3, 0), { fontSize: '15px' });

// per-panel orbital name labels — beneath each mini-panel, as in the source
panelDefs.forEach((d, i) => {
  orbitalLabels.push(addLabel('<i>' + d.name + '</i>',
    d.pos.clone().add(new THREE.Vector3(0, -1.55, 0)),
    { fontSize: '14px', color: '#33527e', bold: true }));
});

// source-style annotation labels
const hybLabel = addLabel('Hybridization ⟶', new THREE.Vector3(0, 3.35, 0), { fontSize: '14px', color: '#444', background: 'rgba(255,255,255,0.85)' });
const tetrLabel = addLabel('Gives a tetrahedral<br>arrangement', new THREE.Vector3(0, 3.35, 0), { fontSize: '13px', color: '#444', background: 'rgba(255,255,255,0.85)' });

// ---- demo steps ----
const steps = [
  {
    title: 'Atomic orbitals',
    narration: 'Before hybridization: a spherical s orbital and three mutually perpendicular p orbitals, each with red (negative) and blue (positive) lobes — shown side by side as in the textbook panels. Toggle each contribution off and on to see it alone.',
    state: { stage: 'Atomic orbitals', chkS: true, chkPx: true, chkPy: true, chkPz: true }
  },
  {
    title: 'Four sp3 hybrids',
    narration: 'After hybridization the orbital distinctions are gone: four equivalent orange hybrids, each with a large lobe and a small back-lobe, point in four different directions.',
    state: { stage: 'sp3 hybrids' }
  },
  {
    title: 'Tetrahedral arrangement',
    narration: 'Viewed together, the four large lobes point to the corners of a tetrahedron at 109.5° to each other — the geometry behind CH4 and other tetrahedral molecules. Orbit to appreciate the symmetry.',
    state: { stage: 'Tetrahedral' }
  }
];
let stepIdx = 2;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  stage = st.state.stage;
  for (const id of ['chkS', 'chkPx', 'chkPy', 'chkPz'])
    if (id in st.state) document.getElementById(id).checked = st.state[id];
  applyStage();
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.narration;
}
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
goToStep(2);

// ---- interactivity ----
hybrids.forEach((h, i) => registerInteractive(h, {
  title: 'sp³ hybrid orbital ' + (i + 1),
  tooltip: 'sp³ hybrid — large lobe to a tetrahedron corner',
  body: 'Each sp³ hybrid is the combination ½(s ± pₓ ± p_y ± p_z). Its large lobe points to a tetrahedron corner; any two lobes meet at 109.47°. The small back-lobe is the opposite-sign remnant.'
}));
registerInteractive(sOrb, {
  title: 's orbital', tooltip: 'Spherical s orbital',
  body: 'The s orbital has equal amplitude in all directions. Mixed into each hybrid, it rounds out the large lobe.'
});
[pxOrb, pyOrb, pzOrb].forEach((p, i) => registerInteractive(p, {
  title: ['pₓ', 'p_y', 'p_z'][i] + ' orbital', tooltip: 'p orbital — signed lobes',
  body: 'A p orbital has two lobes of opposite sign along one axis. Mixing all three p orbitals with the s orbital produces the four directional sp³ hybrids.'
}));
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

